"use client";

import type { ComponentProps } from "react";

import { Shutter } from "@/components/shutter";

/** Porthole window with rim. Color: Dark. */
export function ShutterPortholeDark(props: ComponentProps<typeof Shutter>) {
  return (
    <Shutter
      size="md"
      shape="porthole"
      defaultLevel={45}
      variant="dark"
      label="Porthole · Dark"
      {...props}
    />
  );
}
